    {
        "id": "edc5e203-3ffd-4001-8c44-b9c35c2c75fc",
        "area": null,
        "icon": "🎧",
        "name": "Create a Call Playbook",
        "slug": "create-call-playbook",
        "color": "#0ea5e9",
        "model": null,
        "category": "skill",
