        "author_name": null,
        "description": "Mine external calls for what customers actually say: their words for the problem, objections, competitors and outcomes. Internal; quotes stay on the calls, the product doc gets our words.",
        "forked_from": null,
        "agent_config": {
            "pack_only": true,
            "enabled_tools": [
                "captures",
