        "name": "Deal Reconciler",
        "slug": "deal-reconciler",
        "color": "#f97316",
        "model": null,
        "category": "skill",
        "featured": false,
        "is_system": true,
        "created_at": "2026-07-26T02:33:40.671918+00:00",
        "created_by": null,
        "fork_count": 0,
        "is_default": false,
