            ],
            "response_style": {
                "tone": "terse",
                "format": "structured",
                "always_cite_sources": true
            },
            "preferred_tools": [
                "list_contacts",
                "list_workspace_members",
                "search_claims",
                "list_claims",
                "get_claim",
                "list_actions",
                "list_contact_captures",
