        "updated_at": "2026-10-20T18:55:00.344822+00:00",
        "visibility": "workspace",
        "author_name": null,
        "description": "Write the core message and 3-4 pillars (benefit, mechanism, proof, grade), and the honest answers to customers' objections, into the product doc's Messaging.",
        "forked_from": null,
        "agent_config": {
