        "visibility": "workspace",
        "author_name": null,
        "description": "How Dial8's projects, milestones and cycles work and how to keep them moving: finding a project's work, meetings and documents, status updates, cycles. Loads by itself when you work on projects.",
        "forked_from": null,
        "agent_config": {
            "enabled_tools": [
                "projects",
