        "author_name": null,
        "description": "How Dial8's prospecting works and how to run it well: ideal-customer fit, discovery and scoring, finding people, saving, publishing to the CRM and enrolling. Loads by itself when you prospect.",
        "forked_from": null,
        "agent_config": {
            "enabled_tools": [
                "prospecting",
                "sequences",
                "contacts"
            ],
            "preferred_tools": [
                "list_prospect_lists",
                "research_my_company",
                "create_prospect_list",
                "run_prospect_discovery",
                "wait_for_prospecting_run",
                "list_prospect_entries",
