        "description": "How Dial8's sequences work and how to run outreach well: writing steps, timing and merge fields, enrolling, what sends when and who launches. Loads by itself when you work on sequences.",
        "forked_from": null,
        "agent_config": {
            "enabled_tools": [
                "sequences",
                "contacts"
            ],
            "preferred_tools": [
                "list_sequences",
                "get_sequence",
                "create_sequence",
                "update_sequence",
                "enroll_contacts_in_sequence",
                "remove_from_sequence",
