        "description": "When work customers asked for ships, drafts a short note to each person who asked, in the person's voice. The drafts wait in their mail; nothing is sent.",
        "forked_from": null,
        "agent_config": {
            "material": "asked_by",
            "enabled_tools": [
                "actions",
                "projects",
                "contacts"
            ],
