        "visibility": "workspace",
        "author_name": null,
        "description": "Drafts the week's posts for the person's own account from what they shipped, published and said on their calls; a slow week brings ideas. Each is a card they post themselves.",
        "forked_from": null,
        "agent_config": {
            "material": "post_week",
            "enabled_tools": [
                "content",
                "documents",
