    {
        "id": "33de6044-7d0e-4823-961f-3cd4b25eafd6",
        "area": null,
        "icon": "🎧",
        "name": "Live Sales Copilot",
        "slug": "sales-live",
        "color": "#6366f1",
        "model": null,
        "category": "agent",
        "featured": false,
        "is_system": true,
        "created_at": "2026-09-15T02:12:04.549165+00:00",
        "created_by": null,
        "fork_count": 0,
        "is_default": false,
        "sort_order": 40,
        "updated_at": "2026-10-18T05:18:42.688871+00:00",
        "visibility": "workspace",
        "author_name": null,
        "description": "Your private in-ear copilot during a live sales call — answers the buyer's spec, pricing, and rollout questions from your workspace in the moment, briefs you on who you're meeting, and flags buying signals, objections, and promises you're about to drop.",
        "forked_from": null,
        "agent_config": {
            "capture_mode": "assist_only",
            "enabled_tools": [
                "captures",
                "actions",
                "projects",
                "documents",
                "decisions",
                "emails",
                "contacts",
                "calendar",
                "attachments",
                "initiatives",
                "cycles",
                "comments",
                "calendar_capture",
                "dashboard",
                "notifications",
                "search",
                "flows",
                "knowledge",
                "sequences",
                "evals"
            ],
            "response_style": {
                "tone": "direct",
                "format": "conversational",
                "always_cite_sources": true
